package crypto

// Golden conformance vectors: the hex-encoded public keys derived from
// testSeed ("bpprotocol.org/v1/test-identity") via MakeKyberPair /
// MakeMLDSAPair. Locked so any change to the derivation (library swap,
// seed handling) is caught, and so other implementations can reproduce them.
//
// ML-KEM768 public key = 1184 bytes; ML-DSA-65 public key = 1952 bytes.
const (
	GOLDEN_KYBER = ""
	GOLDEN_MLDSA = ""
)
